using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using RoadGunner;using RoadGunner.Editor;
public static class WastelandInspect {
 public static string Main(){var l=RoadGunnerLevelAuthoring.Current;var lines=new List<string>();lines.Add("scene="+l.gameObject.scene.path);lines.Add("ground local="+l.ground.sharedMesh.bounds+" world="+l.ground.GetComponent<Renderer>().bounds+" transform="+l.ground.transform.position+" rotation="+l.ground.transform.eulerAngles);lines.Add("gameplay="+l.gameplayBounds);lines.Add("cap="+l.session.spawns.tuning.activeCap+" authored="+l.session.spawns.authoredRaiders.Length+" pooled="+l.session.spawns.pool.Length+" buggies="+l.session.spawns.buggyPool.Length+" groups="+l.session.spawns.GroupCount);lines.Add("spawn="+l.playerSpawn.position+" recovery="+string.Join(";",l.recoveryPoints.Select(t=>t.position.ToString())));
 foreach(var root in new[]{l.obstaclesRoot,l.decorationRoot})foreach(Transform section in root){lines.Add("SECTION "+section.name+" p="+section.position+" r="+section.eulerAngles+" s="+section.localScale);foreach(Transform t in section)lines.Add("  "+t.name+" p="+t.position+" s="+t.localScale+" meshes="+t.GetComponentsInChildren<MeshFilter>().Length+" colliders="+t.GetComponentsInChildren<Collider>().Length+" prefab="+PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t));}
 Directory.CreateDirectory("Documentation/RoadGunner/Wasteland-Restore-2026-10-10");File.WriteAllLines("Documentation/RoadGunner/Wasteland-Restore-2026-10-10/BeforeInventory.txt",lines);return string.Join("\n",lines.Take(6));}
}
